import{j as t,Z as n,b as i,c as o,ae as e,A as d,s as l,f as h,q as s,au as c}from"./chunks/framework.CFYg4X4w.js";const P=JSON.parse('{"title":"Agent 后端常见面试题","description":"Agent 后端开发中常见的后端基础、系统设计、高并发、数据库、缓存、消息队列和安全问题。","frontmatter":{"title":"Agent 后端常见面试题","description":"Agent 后端开发中常见的后端基础、系统设计、高并发、数据库、缓存、消息队列和安全问题。","date":"2026-06-11T00:00:00.000Z","tags":["后端","系统设计","面试"],"categories":["面经"]},"headers":[],"relativePath":"interview/agent-backend/backend-questions.md","filePath":"interview/agent-backend/backend-questions.md","lastUpdated":1782271370000}'),A={name:"interview/agent-backend/backend-questions.md"};function b(m,a,_,p,g,u){const r=n("Mermaid");return i(),o("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1781136000000"},[a[1]||(a[1]=e('<h1 id="agent-后端常见面试题" tabindex="-1">Agent 后端常见面试题 <a class="header-anchor" href="#agent-后端常见面试题" aria-label="Permalink to “Agent 后端常见面试题”">​</a></h1><h2 id="一、系统设计" tabindex="-1">一、系统设计 <a class="header-anchor" href="#一、系统设计" aria-label="Permalink to “一、系统设计”">​</a></h2><h3 id="_1-如何设计一个-agent-后端服务" tabindex="-1">1. 如何设计一个 Agent 后端服务？ <a class="header-anchor" href="#_1-如何设计一个-agent-后端服务" aria-label="Permalink to “1. 如何设计一个 Agent 后端服务？”">​</a></h3><p>核心模块：</p><ul><li>API Gateway：鉴权、限流、路由。</li><li>Session Service：会话、上下文、状态管理。</li><li>Agent Runtime：规划、工具调用、模型调用。</li><li>Tool Service：工具注册、执行、权限和审计。</li><li>RAG Service：文档处理、检索、重排、引用。</li><li>Model Gateway：模型路由、重试、降级、成本统计。</li><li>Observability：日志、trace、指标、评测。</li></ul><h3 id="_2-agent-请求链路如何设计" tabindex="-1">2. Agent 请求链路如何设计？ <a class="header-anchor" href="#_2-agent-请求链路如何设计" aria-label="Permalink to “2. Agent 请求链路如何设计？”">​</a></h3>',6)),(i(),d(c,null,{default:l(()=>[s(r,{id:"mermaid-52",graph:"sequenceDiagram%0A%20%20participant%20U%20as%20User%0A%20%20participant%20API%20as%20API%20Server%0A%20%20participant%20A%20as%20Agent%20Runtime%0A%20%20participant%20M%20as%20Model%20Gateway%0A%20%20participant%20T%20as%20Tool%20Service%0A%20%20participant%20R%20as%20RAG%20Service%0A%0A%20%20U-%3E%3EAPI%3A%20user%20message%0A%20%20API-%3E%3EA%3A%20create%20run%0A%20%20A-%3E%3ER%3A%20retrieve%20knowledge%0A%20%20R--%3E%3EA%3A%20context%20chunks%0A%20%20A-%3E%3EM%3A%20LLM%20reasoning%0A%20%20M--%3E%3EA%3A%20tool%20call%20or%20answer%0A%20%20A-%3E%3ET%3A%20execute%20tool%0A%20%20T--%3E%3EA%3A%20observation%0A%20%20A-%3E%3EM%3A%20final%20generation%0A%20%20M--%3E%3EAPI%3A%20answer%20stream%0A%20%20API--%3E%3EU%3A%20streaming%20response%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h3 id="_3-如何做模型网关" tabindex="-1">3. 如何做模型网关？ <a class="header-anchor" href="#_3-如何做模型网关" aria-label="Permalink to “3. 如何做模型网关？”">​</a></h3><p>能力：</p><ul><li>多模型适配，统一 API。</li><li>超时、重试、熔断、降级。</li><li>模型路由，按任务类型选择模型。</li><li>token 统计和成本核算。</li><li>Prompt 模板版本管理。</li><li>流式输出统一封装。</li></ul><h2 id="二、高并发与稳定性" tabindex="-1">二、高并发与稳定性 <a class="header-anchor" href="#二、高并发与稳定性" aria-label="Permalink to “二、高并发与稳定性”">​</a></h2><h3 id="_1-如何做限流" tabindex="-1">1. 如何做限流？ <a class="header-anchor" href="#_1-如何做限流" aria-label="Permalink to “1. 如何做限流？”">​</a></h3><p>常见算法：</p><ul><li>固定窗口</li><li>滑动窗口</li><li>令牌桶</li><li>漏桶</li></ul><p>Agent 场景通常按用户、租户、模型、工具维度组合限流。</p><h3 id="_2-如何做重试" tabindex="-1">2. 如何做重试？ <a class="header-anchor" href="#_2-如何做重试" aria-label="Permalink to “2. 如何做重试？”">​</a></h3><p>原则：</p><ul><li>只对幂等操作自动重试。</li><li>指数退避加 jitter。</li><li>区分 4xx 和 5xx。</li><li>对工具调用设置最大重试次数。</li><li>有副作用工具必须避免重复执行。</li></ul><h3 id="_3-如何做熔断和降级" tabindex="-1">3. 如何做熔断和降级？ <a class="header-anchor" href="#_3-如何做熔断和降级" aria-label="Permalink to “3. 如何做熔断和降级？”">​</a></h3><ul><li>模型服务异常时切换备用模型。</li><li>RAG 失败时降级为不带知识库回答，或提示无法查询资料。</li><li>工具失败时提供人工处理入口。</li><li>高峰期关闭低优先级功能，如复杂 rerank。</li></ul><h2 id="三、数据库与缓存" tabindex="-1">三、数据库与缓存 <a class="header-anchor" href="#三、数据库与缓存" aria-label="Permalink to “三、数据库与缓存”">​</a></h2><h3 id="_1-mysql-索引为什么会失效" tabindex="-1">1. MySQL 索引为什么会失效？ <a class="header-anchor" href="#_1-mysql-索引为什么会失效" aria-label="Permalink to “1. MySQL 索引为什么会失效？”">​</a></h3><p>常见原因：</p><ul><li>对索引列使用函数或表达式。</li><li>隐式类型转换。</li><li><code>like &#39;%xxx&#39;</code> 前缀模糊。</li><li>联合索引不满足最左前缀。</li><li>低选择性字段不适合单独建索引。</li></ul><h3 id="_2-redis-常见数据结构和使用场景" tabindex="-1">2. Redis 常见数据结构和使用场景？ <a class="header-anchor" href="#_2-redis-常见数据结构和使用场景" aria-label="Permalink to “2. Redis 常见数据结构和使用场景？”">​</a></h3><ul><li>String：缓存、计数器、分布式锁。</li><li>Hash：对象缓存。</li><li>List：简单队列。</li><li>Set：去重、标签集合。</li><li>ZSet：排行榜、延迟队列。</li><li>Stream：消息流。</li></ul><h3 id="_3-缓存穿透、击穿、雪崩怎么处理" tabindex="-1">3. 缓存穿透、击穿、雪崩怎么处理？ <a class="header-anchor" href="#_3-缓存穿透、击穿、雪崩怎么处理" aria-label="Permalink to “3. 缓存穿透、击穿、雪崩怎么处理？”">​</a></h3><ul><li>穿透：缓存空值、布隆过滤器。</li><li>击穿：热点 key 互斥锁、逻辑过期。</li><li>雪崩：过期时间加随机值、多级缓存、限流降级。</li></ul><h2 id="四、消息队列" tabindex="-1">四、消息队列 <a class="header-anchor" href="#四、消息队列" aria-label="Permalink to “四、消息队列”">​</a></h2><h3 id="_1-为什么使用-mq" tabindex="-1">1. 为什么使用 MQ？ <a class="header-anchor" href="#_1-为什么使用-mq" aria-label="Permalink to “1. 为什么使用 MQ？”">​</a></h3><ul><li>削峰填谷。</li><li>异步解耦。</li><li>失败重试。</li><li>事件驱动。</li><li>长任务后台化。</li></ul><p>Agent 场景可用于文档入库、Embedding 生成、离线评测、异步工具执行。</p><h3 id="_2-如何保证消息不丢" tabindex="-1">2. 如何保证消息不丢？ <a class="header-anchor" href="#_2-如何保证消息不丢" aria-label="Permalink to “2. 如何保证消息不丢？”">​</a></h3><ul><li>Producer confirm。</li><li>Broker 持久化。</li><li>Consumer ack。</li><li>失败重试和死信队列。</li><li>业务侧幂等处理。</li></ul><h3 id="_3-如何保证幂等" tabindex="-1">3. 如何保证幂等？ <a class="header-anchor" href="#_3-如何保证幂等" aria-label="Permalink to “3. 如何保证幂等？”">​</a></h3><ul><li>请求唯一 id。</li><li>数据库唯一约束。</li><li>Redis setnx。</li><li>状态机校验。</li><li>幂等表记录处理结果。</li></ul><h2 id="五、安全与权限" tabindex="-1">五、安全与权限 <a class="header-anchor" href="#五、安全与权限" aria-label="Permalink to “五、安全与权限”">​</a></h2><h3 id="_1-agent-有哪些安全风险" tabindex="-1">1. Agent 有哪些安全风险？ <a class="header-anchor" href="#_1-agent-有哪些安全风险" aria-label="Permalink to “1. Agent 有哪些安全风险？”">​</a></h3><ul><li>Prompt Injection。</li><li>工具越权调用。</li><li>数据泄露。</li><li>RAG 污染。</li><li>SSRF / 任意文件读取。</li><li>代码执行风险。</li></ul><h3 id="_2-如何防-prompt-injection" tabindex="-1">2. 如何防 Prompt Injection？ <a class="header-anchor" href="#_2-如何防-prompt-injection" aria-label="Permalink to “2. 如何防 Prompt Injection？”">​</a></h3><ul><li>系统指令和用户输入分层。</li><li>工具权限由后端判断，不交给模型。</li><li>RAG 文档中的指令不应被当成系统指令。</li><li>对高危操作做二次确认。</li><li>输出和工具参数做安全校验。</li></ul><h3 id="_3-工具权限怎么设计" tabindex="-1">3. 工具权限怎么设计？ <a class="header-anchor" href="#_3-工具权限怎么设计" aria-label="Permalink to “3. 工具权限怎么设计？”">​</a></h3><ul><li>工具分级：只读、写入、高危。</li><li>用户/租户级 ACL。</li><li>参数级权限校验。</li><li>高危操作审批。</li><li>全链路审计日志。</li></ul><h2 id="六、开放题回答模板" tabindex="-1">六、开放题回答模板 <a class="header-anchor" href="#六、开放题回答模板" aria-label="Permalink to “六、开放题回答模板”">​</a></h2><h3 id="题目-你如何提升一个-agent-系统的成功率" tabindex="-1">题目：你如何提升一个 Agent 系统的成功率？ <a class="header-anchor" href="#题目-你如何提升一个-agent-系统的成功率" aria-label="Permalink to “题目：你如何提升一个 Agent 系统的成功率？”">​</a></h3><p>回答结构：</p><ol><li>先建立评测集，定义成功率和失败类型。</li><li>按链路拆分：意图识别、检索、工具调用、生成。</li><li>针对召回失败优化 RAG，针对工具失败优化 schema 和校验。</li><li>针对生成失败优化 prompt、few-shot 和模型选择。</li><li>上线 trace 和用户反馈，持续回归评测。</li></ol><h3 id="题目-agent-系统如何控制成本" tabindex="-1">题目：Agent 系统如何控制成本？ <a class="header-anchor" href="#题目-agent-系统如何控制成本" aria-label="Permalink to “题目：Agent 系统如何控制成本？”">​</a></h3><p>回答结构：</p><ol><li>模型路由，简单任务走小模型。</li><li>压缩上下文和工具结果。</li><li>缓存 embedding、检索结果和常见答案。</li><li>限制最大轮数和工具调用次数。</li><li>做 token 预算和租户级限额。</li></ol>',43))])}const f=t(A,[["render",b]]);export{P as __pageData,f as default};
